WHEEL = "passagemath-singular==10.8.13"
SOLVER_SECONDS = 41000
OUT = Path("/kaggle/working")


def meminfo(key):
    for line in Path("/proc/meminfo").read_text().splitlines():
        if line.startswith(key + ":"):
            return int(line.split()[1])
    return -1


def rss(pid):
    try:
        for line in Path(f"/proc/{pid}/status").read_text().splitlines():
            if line.startswith("VmRSS:"):
                return int(line.split()[1])
    except OSError:
        return -1
    return -1


def capped(nbytes):
    def apply():
        resource.setrlimit(resource.RLIMIT_AS, (nbytes, nbytes))

    return apply


def main():
    started = time.time()
    subprocess.run([sys.executable, "-m", "pip", "install", "--quiet", WHEEL], check=True)
    candidates = [Path(sysconfig.get_paths()[k]) / "sage_wheels/bin/Singular" for k in ("purelib", "platlib")]
    binary = next(p for p in candidates if p.exists())
    binary.chmod(0o755)
    procs = {}
    for job in JOBS:
        work = OUT / job["name"]
        work.mkdir(exist_ok=True)
        (work / "input.sing").write_text(job["script"] + "\n")
        log = open(work / "singular.log", "w")
        procs[job["name"]] = subprocess.Popen(
            ["timeout", str(SOLVER_SECONDS), str(binary), "-q", "--no-warn", "input.sing"],
            stdout=log, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL, cwd=work,
            preexec_fn=capped(job["as_bytes"]),
        )
    samples = open(OUT / "samples.tsv", "w")
    samples.write("elapsed_s\t" + "\t".join(f"{n}_rss_kib" for n in procs) + "\tmem_available_kib\n")
    stop = threading.Event()

    def sample():
        while not stop.is_set():
            row = []
            for proc in procs.values():
                child = subprocess.run(["pgrep", "-P", str(proc.pid)], capture_output=True, text=True).stdout.split()
                row.append(str(max([rss(int(c)) for c in child] + [rss(proc.pid)])))
            samples.write(f"{time.time() - started:.0f}\t" + "\t".join(row) + f"\t{meminfo('MemAvailable')}\n")
            samples.flush()
            stop.wait(30)

    sampler = threading.Thread(target=sample, daemon=True)
    sampler.start()
    jobs = {}
    for name, proc in procs.items():
        code = proc.wait()
        lines = (OUT / name / "singular.log").read_text(errors="replace").splitlines()
        jobs[name] = {
            "return_code": code,
            "ended_seconds": round(time.time() - started, 1),
            "results": [line for line in lines if line.startswith(("RESULT", "PROGRESS"))],
        }
    stop.set()
    sampler.join()
    record = {
        "label": LABEL,
        "wheel": WHEEL,
        "wall_seconds": round(time.time() - started, 1),
        "peak_child_rss_kib": resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss,
        "mem_total_kib": meminfo("MemTotal"),
        "jobs": jobs,
        "machine": platform.processor() or platform.machine(),
        "python": sys.version.split()[0],
    }
    (OUT / "result.json").write_text(json.dumps(record, indent=1) + "\n")
    print(json.dumps(record))


main()
